<script setup>
import { ref } from 'vue';
import { Link, router, useForm, usePage } from '@inertiajs/vue3';
import AssessmentLayout from './AssessmentLayout.vue';
import { confirmAction } from './confirmAction.js';
const props = defineProps({rubrics:Object,filters:Object,importTemplate:Object,importResult:Object});
const page = usePage(); const search = ref(props.filters?.search || ''); const importing = ref(false);
const importForm = useForm({import_file:null,import_json_text:''});
const filter = () => router.get(route('redesign.rubrics'),{search:search.value || undefined},{preserveState:true,replace:true});
const importJson = () => importForm.post(route('admin.rubrics.import-json'),{forceFormData:true,onSuccess:()=>{importing.value=false;importForm.reset();router.get(route('redesign.rubrics'));}});
const remove = async rubric => {if(await confirmAction(`Hapus rubrik ${rubric.title}?`)) router.delete(route('admin.rubrics.destroy',rubric.id),{onSuccess:()=>router.get(route('redesign.rubrics'))});};
</script>
<template><AssessmentLayout title="Rubric management" subtitle="Kelola kriteria, level, dan pedoman penilaian."><template #action><Link class="primary" :href="route('redesign.rubrics.create')">+ Buat rubrik</Link></template><div class="tabs"><button class="tab" :class="{active:!importing}" @click="importing=false">Semua rubrik</button><button class="tab" :class="{active:importing}" @click="importing=true">Import JSON</button></div><template v-if="importing"><div class="layout"><form class="panel" @submit.prevent="importJson"><h2>Import rubrik JSON</h2><div class="fields"><label class="wide">File JSON<input type="file" accept=".json,.txt,application/json" @change="importForm.import_file=$event.target.files?.[0] || null" /><small class="error">{{ importForm.errors.import_file }}</small></label><label class="wide">Atau tempel JSON<textarea v-model="importForm.import_json_text" rows="12" :placeholder="JSON.stringify(importTemplate?.sample || {},null,2)" /><small class="error">{{ importForm.errors.import_json_text }}</small></label></div><div class="actions"><button class="primary" :disabled="importForm.processing">Import JSON</button><button class="secondary" type="button" @click="importing=false">Batal</button></div></form><aside><section class="panel"><h2>Template</h2><p class="muted">Siapkan kriteria, level, dan deskripsi matriks dalam satu file.</p><a :href="importTemplate?.download_url" download>Unduh template</a><p v-if="importResult" class="success">{{ importResult.title }} berhasil diimport.</p></section></aside></div></template><template v-else><form class="filters" @submit.prevent="filter"><input v-model="search" aria-label="Cari rubrik" placeholder="Cari judul atau deskripsi..." /><button class="action">Filter</button><Link class="secondary" :href="route('redesign.rubrics')">Reset</Link></form><p v-if="page.props.flash?.message" class="success">{{ page.props.flash.message }}</p><section class="panel"><h2>Rubric management</h2><div class="table-wrap"><table><thead><tr><th>Rubrik</th><th>Kriteria</th><th>Level</th><th>Diperbarui</th><th>Aksi</th></tr></thead><tbody><tr v-for="rubric in rubrics?.data || []" :key="rubric.id"><td><Link class="row-link" :href="route('redesign.rubrics.show',rubric.id)">{{ rubric.title }}</Link></td><td>{{ rubric.criteria_count ?? '—' }}</td><td>{{ rubric.levels_count ?? '—' }}</td><td>{{ rubric.updated_at ? new Date(rubric.updated_at).toLocaleDateString('id-ID') : '—' }}</td><td><Link :href="route('redesign.rubrics.show',rubric.id)">Lihat</Link> · <Link :href="route('redesign.rubrics.edit',rubric.id)">Edit</Link> · <button class="delete" type="button" @click="remove(rubric)">Hapus</button></td></tr><tr v-if="!rubrics?.data?.length"><td colspan="5" class="muted">Belum ada rubrik.</td></tr></tbody></table></div><div class="pager"><Link v-for="(link,i) in rubrics?.links || []" :key="i" :href="link.url || '#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label" /></div></section></template></AssessmentLayout></template>
<style scoped>.tab{border:1px solid #dce6e8;border-radius:8px;padding:10px 16px;background:#fff;color:#70858c;cursor:pointer}.tab.active{background:#e5f5f1;color:#007f78}.row-link{font-weight:700;color:#19333d;text-decoration:underline;text-decoration-color:#9ccbc6;text-underline-offset:3px}.delete{border:0;background:none;color:#b74336;cursor:pointer}td a,.panel a{color:#007f78}</style>
